-- Los locales del mapa se acotan a lo que se compra para una previa.
--
-- La 0010 traía también `shop=convenience` de OSM, que en Argentina es un cajón
-- de sastre: entraban pastas caseras, dietéticas y verdulerías ("Piu Pasta" en
-- Bariloche fue el caso que lo destapó). De ese rubro se rescatan sólo los que
-- abren 24/7 — los "24hs" de verdad — y se suman los growshops, que en OSM
-- argentino se etiquetan casi siempre como `shop=cannabis`.
--
-- Rubros válidos de acá en adelante: kiosco, vinoteca, bebidas, growshop, 24hs.
-- Fuente: OpenStreetMap (ODbL).

-- 1. Fuera lo que no es de previa. Va primero para que el seed de abajo pueda
--    volver a insertar, con el rubro correcto, los pocos que sí califican.
delete from public.shops
where kind not in ('kiosco', 'vinoteca', 'bebidas', 'growshop', '24hs');

-- 2. Candado: que no vuelva a entrar un rubro que no sea de previa.
alter table public.shops drop constraint if exists shops_kind_check;
alter table public.shops
  add constraint shops_kind_check
  check (kind in ('kiosco', 'vinoteca', 'bebidas', 'growshop', '24hs'));

-- >>> BEGIN SEED GENERADO — no editar a mano (npm run gen:shops)
-- 2618 locales de 59 ciudades; 350 con horario cargado en OSM.
-- Rubros: kiosco, vinoteca, bebidas, growshop, 24hs. Nada más.
-- Fuente: OpenStreetMap (ODbL).

